 function sla(c){var due=c.openedAt?plusHours(c.openedAt,c.slaHours):null,response=c.openedAt&&c.firstResponseAt?hours(c.openedAt,c.firstResponseAt):null,state='Unknown';if(response!=null)state=response<=c.slaHours?'Met':'Missed';else if(due){var rem=hours(now(),due);state=rem<0?'Overdue':rem<=1?'Due Soon':'Open'}return{due:due,responseHours:response,state:state}}
