 function build(){var rows=connectedCases().concat(localCases()),map={};rows.forEach(function(c){var k=c.source+'|'+c.id;if(!map[k])map[k]=c});rows=Object.keys(map).map(function(k){var c=map[k];c.order=orders(c.company).filter(function(o){return c.orderNumber&&norm(o.number)===norm(c.orderNumber)})[0]||null;c.evidence=evidence(c);return c}).sort(function(a,b){var pw={Critical:4,High:3,Normal:2,Low:1};return(pw[b.priority]||0)-(pw[a.priority]||0)||((b.openedAt?b.openedAt.getTime():0)-(a.openedAt?a.openedAt.getTime():0))});var open=rows.filter(function(c){return ['Resolved','Closed'].indexOf(c.status)<0}),resolved=rows.filter(function(c){return c.status==='Resolved'||c.status==='Closed'}),escalated=open.filter(function(c){return c.escalationLevel&&c.escalationLevel!=='None'}),slaOver=open.filter(function(c){return c.sla.state==='Overdue'||c.sla.state==='Missed'}),promiseRows=[];rows.forEach(function(c){c.promiseRows.forEach(function(p){promiseRows.push({case:c,promise:p})})});promiseRows.sort(function(a,b){return(a.promise.dueAt?a.promise.dueAt.getTime():Infinity)-(b.promise.dueAt?b.promise.dueAt.getTime():Infinity)});var overduePromises=promiseRows.filter(function(x){return x.promise.state==='Overdue'}),avgResolution=[];resolved.forEach(function(c){if(c.openedAt&&c.resolvedAt){var d=hours(c.openedAt,c.resolvedAt);if(d!=null&&d>=0)avgResolution.push(d)}});return{cases:rows,open:open,resolved:resolved,escalated:escalated,slaOver:slaOver,promises:promiseRows,overduePromises:overduePromises,avgResolution:avgResolution.length?avgResolution.reduce(function(s,x){return s+x},0)/avgResolution.length:null,companies:companies(),view:store()}}
 function section(k,t,note){return'<div class="cs3-section-head"><div><div class="cs3-section-kick">'+k+'</div><div class="cs3-section-title">'+t+'</div></div><div class="cs3-section-note">'+note+'</div></div>'} function kpi(l,v,s){return'<div class="cs3-kpi"><div class="cs3-kpi-label">'+esc(l)+'</div><div class="cs3-kpi-value">'+v+'</div><div class="cs3-kpi-sub">'+s+'</div></div>'} function empty(t,c){return'<div class="cs3-empty"><strong>'+esc(t)+'</strong><span>'+esc(c)+'</span></div>'}
