 function posture(g){if(!g.cases.length)return{tone:'info',title:'The Service Case Center is ready for its first case',copy:'Create a case, document the customer impact, own the next promise, and record the resolution.'};if(g.slaOver.length||g.overduePromises.length)return{tone:'risk',title:'Customer response or promise commitments are overdue',copy:(g.slaOver.length+g.overduePromises.length)+' overdue service commitments require attention.'};if(g.escalated.length)return{tone:'warn',title:'Escalated cases need coordinated ownership',copy:g.escalated.length+' open case'+(g.escalated.length===1?' is':'s are')+' escalated beyond normal rep ownership.'};return{tone:'good',title:'Open cases have controlled ownership',copy:'No visible response SLA or customer promise is currently overdue.'}}
 function caseIcon(c){if(c.type==='Production Delay')return'🏭';if(c.type==='Artwork / Proof')return'🎨';if(c.type==='Shipping')return'🚚';if(c.type==='Billing')return'💳';if(c.type==='Return / Replacement')return'↩';if(c.type==='Product Quality')return'🔍';return'🛠'}
 function riskRows(g){var rows=[];g.open.forEach(function(c){if(c.priority==='Critical')rows.push({case:c,level:'high',title:'Critical case',copy:c.description||c.subject});if(c.sla.state==='Overdue'||c.sla.state==='Missed')rows.push({case:c,level:'high',title:'Response target '+c.sla.state.toLowerCase(),copy:c.firstResponseAt?'First response exceeded the entered target.':'No first response is recorded.'});if(c.promiseRows.some(function(p){return p.state==='Overdue'}))rows.push({case:c,level:'high',title:'Customer promise overdue',copy:'At least one recorded customer commitment is past due.'});if(c.escalationLevel!=='None')rows.push({case:c,level:'medium',title:'Escalated to '+c.escalationLevel,copy:c.escalationReason||'Escalation reason not recorded.'});if(!c.nextStep&&['Resolved','Closed'].indexOf(c.status)<0)rows.push({case:c,level:'medium',title:'Next step is missing',copy:'Open service work has no documented next action.'})});return rows.slice(0,12)}
