 function command(g){var p=posture(g),risks=riskRows(g);return section('Case command center','Customer-impact work, ownership, and promises','Cases organize service work. They do not automatically assign fault, financial impact, or disciplinary responsibility.')+'<div class="cs3-summary"><div class="cs3-summary-label">Service interpretation</div><div class="cs3-summary-title">'+esc(p.title)+'</div><div class="cs3-summary-copy">'+esc(p.copy)+'</div></div>'+section('Highest-priority service moves','SLA, promise, escalation, and next-step risks','The queue identifies incomplete service controls without deciding who caused the issue.')+(risks.length?'<div class="cs3-priority-list">'+risks.map(priorityRow).join('')+'</div>':empty('No urgent case exceptions','No open case currently triggers an overdue SLA, customer-promise, escalation, or missing-next-step warning.'))+section('Open case mix','Visible open cases by status','Connected and local cases are combined only for the logged-in rep.')+'<div class="cs3-panel"><div class="cs3-chart"><canvas id="cs3-chart"></canvas></div></div>'}
 function filterbar(g){return'<div class="cs3-filterbar"><input id="cs3-search" type="search" placeholder="Search case, company, order, subject…" oninput="_rp2CasesFilter()"><select id="cs3-status" onchange="_rp2CasesFilter()"><option value="">All statuses</option>'+STATUSES.map(function(x){return'<option>'+x+'</option>'}).join('')+'</select><select id="cs3-priority" onchange="_rp2CasesFilter()"><option value="">Any priority</option>'+PRIORITIES.map(function(x){return'<option>'+x+'</option>'}).join('')+'</select><select id="cs3-type" onchange="_rp2CasesFilter()"><option value="">Any case type</option>'+TYPES.map(function(x){return'<option>'+x+'</option>'}).join('')+'</select><select id="cs3-source" onchange="_rp2CasesFilter()"><option value="">Any source</option><option value="local">Local</option><option value="connected">Connected</option></select><div id="cs3-count" class="cs3-filtercount">'+g.cases.length+' shown</div></div>'}
