 function queue(g){return section('Case queue','Every visible customer-service case','Connected cases remain read-only until imported. Local cases support full ownership, promises, escalation, and resolution.')+'<div class="cs3-actions" style="margin-top:0"><button class="cs3-btn primary" onclick="_rp2CasesNew()">＋ New case</button></div>'+filterbar(g)+(g.cases.length?'<div class="cs3-list">'+g.cases.map(caseCard).join('')+'</div>':empty('No service cases are available','Create the first local case or connect an assigned case source.'))}
 function escalations(g){return section('Escalation center','Cases requiring manager, production, art, customer care, accounting, or executive coordination','Escalation identifies required support. It does not establish fault or blame.')+(g.escalated.length?'<div class="cs3-list">'+g.escalated.map(caseCard).join('')+'</div>':empty('No open case is escalated','Escalated local and connected cases will appear here.'))}
 function promiseRow(x){var p=x.promise,c=x.case;return'<div class="cs3-promise '+(p.state==='Overdue'?'overdue':p.state==='Completed'?'done':'')+'"><div class="cs3-promise-icon">📅</div><div><div class="cs3-promise-title">'+esc(p.title+' · '+c.company)+'</div><div class="cs3-promise-copy">'+esc(c.caseNumber+' · '+(p.detail||c.subject)+' · Owner '+(p.owner||c.owner))+'</div></div><div class="cs3-promise-side">'+fmt(p.dueAt)+' · '+p.state+'<br>'+(c.editable&&p.status!=='Completed'?'<button class="cs3-mini-btn good" onclick="_rp2CasesCompletePromise(\''+encodeURIComponent(c.key)+'\',\''+encodeURIComponent(p.id)+'\')">Complete</button>':'')+'<button class="cs3-mini-btn blue" onclick="_rp2CasesTask(\''+encodeURIComponent(c.key)+'\',\''+encodeURIComponent(p.id)+'\')">Action Center</button></div></div>'}
 function promisesView(g){var overdue=g.promises.filter(function(x){return x.promise.state==='Overdue'}),today=g.promises.filter(function(x){return x.promise.state==='Today'}),future=g.promises.filter(function(x){return x.promise.state==='Upcoming'}),done=g.promises.filter(function(x){return x.promise.state==='Completed'});function block(k,t,rows,n){return section(k,t,n)+(rows.length?'<div class="cs3-list">'+rows.map(promiseRow).join('')+'</div>':empty('Nothing in this group','No customer promise matches this timing state.'))}return block('Immediate','Overdue customer promises',overdue,'Recorded commitments that are past due.')+block('Today','Promises due today',today,'Customer commitments due today.')+block('Future','Upcoming promises',future.slice(0,80),'Future customer commitments.')+block('Completed','Recently completed promises',done.slice(-40).reverse(),'Completed customer commitments with recorded outcomes.')}
 function resolution(g){var ready=g.open.filter(function(c){return c.resolutionSummary||c.status==='Action Required'}),resolved=g.resolved;return section('Resolution workspace','Move from investigation to documented customer outcome','A case is not resolved merely because activity stopped. Record the resolution, customer outcome, date, and any prevention step.')+section('Ready for resolution review','Cases with resolution content or action-required status','Review completeness before marking Resolved or Closed.')+(ready.length?'<div class="cs3-list">'+ready.map(caseCard).join('')+'</div>':empty('No case is ready for resolution review','Add resolution details to a local case when the customer issue is actually addressed.'))+section('Resolved and closed cases','Completed service history','Resolution time appears only when both opened and resolved timestamps exist.')+(resolved.length?'<div class="cs3-list">'+resolved.map(caseCard).join('')+'</div>':empty('No case is resolved or closed','Resolved cases will appear here.'))}
 function countBy(rows,fn){var m={};rows.forEach(function(x){var k=fn(x)||'Unknown';m[k]=(m[k]||0)+1});return Object.keys(m).map(function(k){return{name:k,value:m[k]}}).sort(function(a,b){return b.value-a.value})}
 function prevention(g){var roots=countBy(g.cases,function(c){return c.rootCause||'Unconfirmed'}),types=countBy(g.cases,function(c){return c.type||'Other'}),confirmed=g.cases.filter(function(c){return c.rootCause&&c.rootCause!=='Unconfirmed'});return section('Root cause and prevention','Document confirmed causes and corrective actions without guessing','Connected art-error and credit-memo records can support investigation, but they do not automatically establish case responsibility.')+'<div class="cs3-insight-grid"><div class="cs3-insight"><div class="cs3-insight-icon">◎</div><div class="cs3-insight-label">Cases with confirmed root cause</div><div class="cs3-insight-value">'+confirmed.length+'</div><div class="cs3-insight-copy">'+(g.cases.length?Math.round(confirmed.length/g.cases.length*100):0)+'% of visible cases.</div></div><div class="cs3-insight"><div class="cs3-insight-icon">?</div><div class="cs3-insight-label">Unconfirmed cause</div><div class="cs3-insight-value">'+g.cases.filter(function(c){return c.rootCause==='Unconfirmed'}).length+'</div><div class="cs3-insight-copy">Incomplete investigation remains explicitly unconfirmed.</div></div><div class="cs3-insight"><div class="cs3-insight-icon">🛡</div><div class="cs3-insight-label">Prevention plans</div><div class="cs3-insight-value">'+g.cases.filter(function(c){return !!c.preventionPlan}).length+'</div><div class="cs3-insight-copy">Cases with a documented prevention or corrective-action plan.</div></div><div class="cs3-insight"><div class="cs3-insight-icon">💲</div><div class="cs3-insight-label">Verified entered impact</div><div class="cs3-insight-value">'+money(g.cases.filter(function(c){return c.financialImpactVerified}).reduce(function(s,c){return s+c.financialImpact},0))+'</div><div class="cs3-insight-copy">Only manually verified case-impact values are included.</div></div></div>'+section('Root-cause distribution','Confirmed and unconfirmed case causes','Unconfirmed remains a legitimate category until investigation supports another cause.')+'<div class="cs3-priority-list">'+roots.map(function(r){return'<div class="cs3-priority"><div class="cs3-priority-icon">◎</div><div><div class="cs3-priority-title">'+esc(r.name)+'</div><div class="cs3-priority-copy">'+r.value+' visible case'+(r.value===1?'':'s')+'</div></div><div class="cs3-priority-side">'+Math.round(r.value/Math.max(1,g.cases.length)*100)+'%</div></div>'}).join('')+'</div>'+section('Case-type chart','Visible case volume by category','Case type describes the reported issue—not the confirmed cause.')+'<div class="cs3-panel"><div class="cs3-chart"><canvas id="cs3-chart"></canvas></div></div>'}
 function analytics(g){var firstResponses=g.cases.filter(function(c){return c.sla.responseHours!=null}),met=firstResponses.filter(function(c){return c.sla.state==='Met'}).length,rate=firstResponses.length?Math.round(met/firstResponses.length*100):0,csat=g.cases.filter(function(c){return c.csat>0}),avgCsat=csat.length?(csat.reduce(function(s,c){return s+c.csat},0)/csat.length).toFixed(1):'—';return section('Service analytics','Response, resolution, escalation, promise, and customer-outcome evidence','Metrics rely on recorded timestamps and outcomes. Missing data is not silently treated as success.')+'<div class="cs3-insight-grid"><div class="cs3-insight"><div class="cs3-insight-icon">⏱</div><div class="cs3-insight-label">Response target met</div><div class="cs3-insight-value">'+rate+'%</div><div class="cs3-insight-copy">'+met+' of '+firstResponses.length+' cases with a recorded first response.</div></div><div class="cs3-insight"><div class="cs3-insight-icon">✓</div><div class="cs3-insight-label">Resolved cases</div><div class="cs3-insight-value">'+g.resolved.length+'</div><div class="cs3-insight-copy">'+(g.avgResolution==null?'Resolution time unavailable':g.avgResolution.toFixed(1)+' average hours to resolution')+'.</div></div><div class="cs3-insight"><div class="cs3-insight-icon">⚠</div><div class="cs3-insight-label">Open escalations</div><div class="cs3-insight-value">'+g.escalated.length+'</div><div class="cs3-insight-copy">Open cases with a recorded escalation team.</div></div><div class="cs3-insight"><div class="cs3-insight-icon">★</div><div class="cs3-insight-label">Average recorded CSAT</div><div class="cs3-insight-value">'+avgCsat+'</div><div class="cs3-insight-copy">'+csat.length+' cases include a satisfaction score.</div></div></div>'+section('Status and case-type chart','Visible service volume','The chart reflects cases, not orders, credits, or financial impact.')+'<div class="cs3-panel"><div class="cs3-chart"><canvas id="cs3-chart"></canvas></div></div>'}
 function history(g){var rows=[];arr(g.view.data.events).forEach(function(e){rows.push({date:stamp(e.at),type:e.type,title:e.title,copy:e.copy})});g.cases.filter(function(c){return c.source==='local'}).forEach(function(c){arr(c.history).forEach(function(h){rows.push({date:stamp(h.at||h.date),type:h.type||'Case event',title:c.caseNumber+' · '+c.company,copy:h.copy||h.note||''})})});rows=rows.filter(function(r){return r.date}).sort(function(a,b){return b.date-a.date});return section('Case audit history','Creation, updates, escalation, promises, tasks, resolution, and closure','Connected source cases remain read-only and do not generate local mutation events until imported.')+(rows.length?'<div class="cs3-history">'+rows.slice(0,400).map(function(r){return'<div class="cs3-history-row"><div class="cs3-history-date">'+fmtTime(r.date)+'</div><div class="cs3-history-type">'+esc(r.type)+'</div><div class="cs3-history-title">'+esc(r.title)+'</div><div class="cs3-history-copy">'+esc(r.copy)+'</div></div>'}).join('')+'</div>':empty('No local case audit events are recorded','Create, import, update, promise, escalate, resolve, or close a local case to begin the audit trail.'))+section('Audit event chart','Cumulative local service-case events','This chart reflects rep-scoped local browser history.')+'<div class="cs3-panel"><div class="cs3-chart"><canvas id="cs3-chart"></canvas></div></div>'}
 function formField(label,idv,value,type,options){if(type==='textarea')return'<div class="cs3-field"><label>'+label+'</label><textarea id="'+idv+'">'+esc(value||'')+'</textarea></div>';if(type==='select')return'<div class="cs3-field"><label>'+label+'</label><select id="'+idv+'">'+options.map(function(o){var v=typeof o==='string'?o:o.value,l=typeof o==='string'?o:o.label;return'<option value="'+esc(v)+'" '+(String(value||'')===String(v)?'selected':'')+'>'+esc(l)+'</option>'}).join('')+'</select></div>';return'<div class="cs3-field"><label>'+label+'</label><input id="'+idv+'" type="'+(type||'text')+'" value="'+esc(value||'')+'"></div>'}
 function caseForm(g,c){var company=c&&c.company||'',cts=contacts(company),ords=orders(company);return'<div class="cs3-modal-wrap" onclick="if(event.target===this)_rp2CasesClose()"><aside class="cs3-modal"><div class="cs3-modal-head"><div><div class="cs3-modal-icon">'+(c?'✎':'＋')+'</div><div class="cs3-modal-kick">'+(c?'Edit local case':'Create service case')+'</div><div class="cs3-modal-title">'+(c?esc(c.caseNumber):'Capture the issue and customer promise')+'</div><div class="cs3-modal-sub">Document facts, ownership, response timing, escalation, resolution, and prevention without assuming blame.</div></div><button class="cs3-close" onclick="_rp2CasesClose()">×</button></div><div class="cs3-form"><div class="cs3-form-grid-3">'+formField('Case number','cs3-f-number',c&&c.caseNumber||('CASE-'+Date.now().toString().slice(-7)))+formField('Status','cs3-f-status',c&&c.status||'New','select',STATUSES)+formField('Priority','cs3-f-priority',c&&c.priority||'Normal','select',PRIORITIES)+'</div><div class="cs3-form-grid">'+formField('Company','cs3-f-company',company,'select',[{value:'',label:'Choose company'}].concat(g.companies.map(function(x){return{value:x,label:x}})))+formField('New company name','cs3-f-newcompany','')+'</div><div class="cs3-form-grid-3">'+formField('Contact','cs3-f-contact',c&&c.contactId||'','select',[{value:'',label:'No contact linked'}].concat(cts.map(function(x){return{value:x.id,label:x.name}})))+formField('Order number','cs3-f-order',c&&c.orderNumber||'','select',[{value:'',label:'No order linked'}].concat(ords.map(function(x){return{value:x.number,label:x.number+' · '+money(x.value)}})))+formField('Case type','cs3-f-type',c&&c.type||'Order Issue','select',TYPES)+'</div>'+formField('Subject','cs3-f-subject',c&&c.subject||'')+formField('Customer issue / impact','cs3-f-description',c&&c.description||'','textarea')+'<div class="cs3-form-grid-3">'+formField('Opened date and time','cs3-f-opened',localDateTime(c&&c.openedAt||now()),'datetime-local')+formField('First response date and time','cs3-f-response',localDateTime(c&&c.firstResponseAt),'datetime-local')+formField('Response target hours','cs3-f-slahours',c&&c.slaHours||4,'number')+'</div><div class="cs3-form-grid-3">'+formField('Owner','cs3-f-owner',c&&c.owner||_rp2.rep)+formField('Customer sentiment','cs3-f-sentiment',c&&c.sentiment||'Unknown','select',['Unknown','Calm','Concerned','Frustrated','Angry','Relieved','Satisfied'])+formField('Customer deadline','cs3-f-deadline',localDateTime(c&&c.customerDeadline),'datetime-local')+'</div><div class="cs3-form-grid">'+formField('Next update / touch','cs3-f-nextupdate',localDateTime(c&&c.nextUpdateAt),'datetime-local')+formField('Next step','cs3-f-nextstep',c&&c.nextStep||'','textarea')+'</div><div class="cs3-form-grid-3">'+formField('Escalation team','cs3-f-escalation',c&&c.escalationLevel||'None','select',ESCALATIONS)+formField('Escalated date','cs3-f-escalated',localDateTime(c&&c.escalatedAt),'datetime-local')+formField('Responsibility status','cs3-f-responsibility',c&&c.responsibility||'Unconfirmed','select',['Unconfirmed','Shared','Customer','Carrier','Vendor','Internal Process','Rep','Other'])+'</div>'+formField('Escalation reason','cs3-f-escreason',c&&c.escalationReason||'','textarea')+'<div class="cs3-form-grid">'+formField('Root cause','cs3-f-root',c&&c.rootCause||'Unconfirmed','select',ROOTS)+formField('Prevention / corrective action','cs3-f-prevention',c&&c.preventionPlan||'','textarea')+'</div><div class="cs3-form-grid-3">'+formField('Entered financial impact','cs3-f-impact',c&&c.financialImpact||0,'number')+formField('Impact verified','cs3-f-impactverified',c&&c.financialImpactVerified?'Yes':'No','select',['No','Yes'])+formField('CSAT score','cs3-f-csat',c&&c.csat||0,'number')+'</div>'+formField('Resolution summary','cs3-f-resolution',c&&c.resolutionSummary||'','textarea')+'<div class="cs3-form-grid">'+formField('Customer outcome','cs3-f-outcome',c&&c.customerOutcome||'','textarea')+formField('Resolved date and time','cs3-f-resolved',localDateTime(c&&c.resolvedAt),'datetime-local')+'</div></div><div class="cs3-disclosure"><strong>Fairness and integrity:</strong> responsibility and root cause default to Unconfirmed. Order value is not financial impact. Only a manually verified impact value is included in case-impact analytics.</div><div class="cs3-modal-actions"><button class="cs3-btn" onclick="_rp2CasesClose()">Cancel</button>'+(c?'<button class="cs3-btn" onclick="_rp2CasesDelete(\''+encodeURIComponent(c.key)+'\')">Delete local case</button>':'')+'<button class="cs3-btn primary" onclick="_rp2CasesSave(\''+(c?encodeURIComponent(c.key):'')+'\')">'+(c?'Save changes':'Create case')+'</button></div></aside></div>'}
 function detail(g,c){var ev=c.evidence.length?'<div class="cs3-priority-list">'+c.evidence.map(function(e){return'<div class="cs3-priority medium"><div class="cs3-priority-icon">i</div><div><div class="cs3-priority-title">'+esc(e.type)+'</div><div class="cs3-priority-copy">'+esc(e.copy)+'</div></div><div class="cs3-priority-side">Supporting evidence</div></div>'}).join('')+'</div>':empty('No connected supporting evidence','No exact order-number art-error or credit-memo record is visible.');var promisesHtml=c.promiseRows.length?'<div class="cs3-list">'+c.promiseRows.map(function(p){return promiseRow({case:c,promise:p})}).join('')+'</div>':empty('No customer promise is recorded','Add a dated commitment when a customer-facing promise is made.');return'<div class="cs3-modal-wrap" onclick="if(event.target===this)_rp2CasesClose()"><aside class="cs3-modal"><div class="cs3-modal-head"><div><div class="cs3-modal-icon">'+caseIcon(c)+'</div><div class="cs3-modal-kick">'+esc(c.caseNumber+' · '+c.priority+' · '+c.status+' · '+(c.source==='local'?'Local Case Center':'Connected source'))+'</div><div class="cs3-modal-title">'+esc(c.subject)+'</div><div class="cs3-modal-sub">'+esc(c.company||'Company not recorded')+(c.contactName?' · '+esc(c.contactName):'')+(c.orderNumber?' · Order '+esc(c.orderNumber):'')+'</div></div><button class="cs3-close" onclick="_rp2CasesClose()">×</button></div><div class="cs3-detail-grid"><div class="cs3-detail"><div class="cs3-detail-label">Issue and customer impact</div><div class="cs3-detail-value">'+esc(c.description||'Not recorded')+'</div></div><div class="cs3-detail"><div class="cs3-detail-label">Response and ownership</div><div class="cs3-detail-value">Owner '+esc(c.owner)+'\nSLA '+esc(c.sla.state)+'\nDue '+fmtTime(c.sla.due)+'\nFirst response '+fmtTime(c.firstResponseAt)+'</div></div><div class="cs3-detail"><div class="cs3-detail-label">Next commitment</div><div class="cs3-detail-value">'+esc(c.nextStep||'No next step recorded')+'\nNext update '+fmtTime(c.nextUpdateAt)+'\nCustomer deadline '+fmtTime(c.customerDeadline)+'</div></div><div class="cs3-detail"><div class="cs3-detail-label">Escalation</div><div class="cs3-detail-value">'+esc(c.escalationLevel)+'\n'+esc(c.escalationReason||'No escalation reason recorded')+'</div></div><div class="cs3-detail"><div class="cs3-detail-label">Cause and responsibility</div><div class="cs3-detail-value">Root cause '+esc(c.rootCause)+'\nResponsibility '+esc(c.responsibility)+'\nThese remain unconfirmed unless deliberately documented.</div></div><div class="cs3-detail"><div class="cs3-detail-label">Financial context</div><div class="cs3-detail-value">'+(c.financialImpactVerified?money(c.financialImpact)+' verified entered impact':'No verified financial impact')+(c.order?'\nLinked order value '+money(c.order.value)+' — context only':'')+'</div></div><div class="cs3-detail"><div class="cs3-detail-label">Resolution</div><div class="cs3-detail-value">'+esc(c.resolutionSummary||'No resolution recorded')+'\n'+esc(c.customerOutcome||'No customer outcome recorded')+'\nResolved '+fmtTime(c.resolvedAt)+'</div></div><div class="cs3-detail"><div class="cs3-detail-label">Prevention</div><div class="cs3-detail-value">'+esc(c.preventionPlan||'No prevention plan recorded')+'</div></div></div>'+section('Customer promises','Dated commitments and outcomes','Promise completion requires a recorded result.')+promisesHtml+'<div class="cs3-actions"><button class="cs3-btn good" onclick="_rp2CasesNewPromise(\''+encodeURIComponent(c.key)+'\')">＋ Add promise</button></div>'+section('Connected supporting evidence','Exact order-number records only','Evidence supports investigation but does not automatically establish cause, blame, or impact.')+ev+'<div class="cs3-disclosure"><strong>Case integrity:</strong> a complaint is not proof of rep fault; a linked order value is not case impact; a case is not resolved until the resolution and customer outcome are recorded.</div><div class="cs3-modal-actions"><button class="cs3-btn" onclick="_rp2CasesClose()">Close</button><button class="cs3-btn blue" onclick="_rp2CasesOpenCompany(\''+encodeURIComponent(c.company)+'\')">Company</button><button class="cs3-btn" onclick="_rp2CasesTask(\''+encodeURIComponent(c.key)+'\',\'\')">Action Center</button>'+(c.editable?'<button class="cs3-btn primary" onclick="_rp2CasesEdit(\''+encodeURIComponent(c.key)+'\')">Edit case</button>':'<button class="cs3-btn good" onclick="_rp2CasesImport(\''+encodeURIComponent(c.key)+'\')">Import locally</button>')+'</div></aside></div>'}
 function promiseForm(c){return'<div class="cs3-modal-wrap" onclick="if(event.target===this)_rp2CasesClose()"><aside class="cs3-modal"><div class="cs3-modal-head"><div><div class="cs3-modal-icon">📅</div><div class="cs3-modal-kick">Add customer promise</div><div class="cs3-modal-title">'+esc(c.caseNumber+' · '+c.company)+'</div><div class="cs3-modal-sub">Record exactly what was promised, who owns it, and when it is due.</div></div><button class="cs3-close" onclick="_rp2CasesClose()">×</button></div><div class="cs3-form">'+formField('Promise title','cs3-p-title','Customer update')+formField('Promise detail','cs3-p-detail','','textarea')+'<div class="cs3-form-grid">'+formField('Due date and time','cs3-p-due',localDateTime(c.nextUpdateAt||now()),'datetime-local')+formField('Owner','cs3-p-owner',c.owner||_rp2.rep)+'</div></div><div class="cs3-modal-actions"><button class="cs3-btn" onclick="_rp2CasesClose()">Cancel</button><button class="cs3-btn primary" onclick="_rp2CasesSavePromise(\''+encodeURIComponent(c.key)+'\')">Add promise</button></div></aside></div>'}
 function completePromiseForm(c,p){return'<div class="cs3-modal-wrap" onclick="if(event.target===this)_rp2CasesClose()"><aside class="cs3-modal"><div class="cs3-modal-head"><div><div class="cs3-modal-icon">✓</div><div class="cs3-modal-kick">Complete customer promise</div><div class="cs3-modal-title">'+esc(p.title)+'</div><div class="cs3-modal-sub">'+esc(c.caseNumber+' · '+c.company+' · Due '+fmtTime(p.dueAt))+'</div></div><button class="cs3-close" onclick="_rp2CasesClose()">×</button></div><div class="cs3-form">'+formField('Completed date and time','cs3-pc-date',localDateTime(now()),'datetime-local')+formField('Actual outcome','cs3-pc-outcome','','textarea')+'</div><div class="cs3-modal-actions"><button class="cs3-btn" onclick="_rp2CasesClose()">Cancel</button><button class="cs3-btn primary" onclick="_rp2CasesSavePromiseCompletion(\''+encodeURIComponent(c.key)+'\',\''+encodeURIComponent(p.id)+'\')">Complete promise</button></div></aside></div>'}
 function modal(g){var m=window._rp2CasesModal;if(!m)return'';if(m.mode==='new')return caseForm(g,null);var c=m.key?g.cases.filter(function(x){return x.key===decodeURIComponent(m.key)})[0]:null;if(m.mode==='detail'&&c)return detail(g,c);if(m.mode==='edit'&&c&&c.editable)return caseForm(g,c);if(m.mode==='promise'&&c&&c.editable)return promiseForm(c);if(m.mode==='completePromise'&&c&&c.editable){var p=c.promiseRows.filter(function(x){return x.id===decodeURIComponent(m.promiseId)})[0];if(p)return completePromiseForm(c,p)}return''}
 function render(){var page=document.getElementById('rp2-page');if(page)page.innerHTML=window._rp2CasesV3();setTimeout(function(){try{window._rp2CasesDraw();window._rp2CasesFilter()}catch(e){}},0)} function val(idv){var e=document.getElementById(idv);return e?clean(e.value):''}
 function localLoc(key){var idv=String(key||'').replace(/^local\|/,'');var b=store(),idx=b.data.cases.findIndex(function(c){return c&&String(c.id)===idv});return{bucket:b,index:idx,item:idx>=0?b.data.cases[idx]:null,id:idv}}
 function saveRaw(obj){var b=store(),idx=b.data.cases.findIndex(function(c){return c&&String(c.id)===String(obj.id)});if(idx>=0)b.data.cases[idx]=obj;else b.data.cases.push(obj);saveStore(b)}
 function selectedText(idv,rows){var v=val(idv),r=rows.filter(function(x){return String(x.id)===String(v)})[0];return r?r.name||r.number||'':''}
 function addCRMActivity(c,type,detail,outcome){if(!c.company)return;var b=account(c.company,true),at=new Date().toISOString();b.data.activities.push({id:id('act'),source:'local',contactId:c.contactId||'',contactName:c.contactName||'',type:type,subject:c.caseNumber+' · '+c.subject,detail:detail||'',outcome:outcome||'',date:iso(now()),nextStep:c.nextStep||'',nextDate:c.nextUpdateAt||'',caseId:c.id,caseNumber:c.caseNumber,createdAt:at,updatedAt:at});saveAccount(b)}
